window.skillUpFocusedPostTranscriptionalModificationQuestions=dedicated([["What is RNA processing of a primary transcript?",["Modification of RNA after or during its synthesis","Synthesis of RNA from a DNA template without processing","Synthesis of a polypeptide from mRNA","Replication of a DNA template"],0,"Primary RNA is processed into functional RNA."],["What are three common processing events for eukaryotic pre-mRNA?",["Replication, mitosis and meiosis","Capping, splicing and polyadenylation","Translation, folding and secretion","Glycolysis, respiration and fermentation"],1,"These events help generate mature messenger RNA."],["Which end receives the typical eukaryotic mRNA cap?",["Both ends always","3 prime end","5 prime end","Every internal base"],2,"Capping modifies the newly synthesized 5 prime end."],["What is the typical mRNA cap nucleotide?",["Uridine triphosphate only","Thymidine","Deoxyadenosine","7-methylguanosine"],3,"The cap contains methylated guanosine."],["[Enrichment] What unusual linkage joins the cap to mRNA?",["5 prime–5 prime triphosphate","3 prime–3 prime peptide","2 prime–2 prime disulfide","Normal peptide linkage"],0,"The cap is connected by a reversed triphosphate bridge."],["Which function is associated with the 5 prime cap?",["DNA replication initiation","Protection and translation initiation","Amino acid synthesis","Chromosome segregation"],1,"Cap-binding proteins aid stability and translation."],["What is RNA splicing?",["Copying RNA into DNA","Removal of all exons","Removal of introns and joining of exons","Addition of a poly(A) tail"],2,"Splicing produces a continuous mature RNA sequence."],["What is an intron?",["A lipid molecule","A protein active site","A DNA replication origin","A transcribed sequence removed during splicing"],3,"Introns are excised from the primary transcript."],["What is an exon?",["A sequence retained in the mature spliced RNA","A sequence always removed","A protein-only segment","A chromosome centromere"],0,"Exons remain after splicing and may include untranslated regions."],["[Enrichment] Which complex performs most nuclear pre-mRNA splicing?",["Ribosome","Spliceosome","Proteasome","DNA replisome"],1,"The spliceosome contains small nuclear RNAs and proteins."],["[Enrichment] What are snRNPs?",["DNA polymerases","Free fatty acids","Small nuclear ribonucleoproteins","Membrane channels"],2,"snRNPs combine snRNA with proteins in splicing complexes."],["[Enrichment] What intermediate forms during typical spliceosomal intron removal?",["Lipid bilayer","DNA double helix","Polypeptide chain","Lariat"],3,"The intron forms a branched lariat intermediate."],["[Enrichment] Which nucleotide commonly acts as the branch point in spliceosomal splicing?",["Adenine","Thymine","Guanine always","Cytosine always"],0,"A branch-point adenosine initiates lariat formation."],["[Enrichment] What is alternative splicing?",["Random removal of all RNA","Different exon combinations from one primary transcript","DNA replication without primers","Protein degradation"],1,"Alternative exon selection can generate multiple RNA isoforms."],["[Enrichment] What is a consequence of alternative splicing?",["Chromosome number doubles","All genes become identical","Increased transcript and protein diversity","DNA loses every intron"],2,"Different mature transcripts may encode different protein isoforms."],["Which end receives the poly(A) tail of most eukaryotic mRNAs?",["Both ends always","5 prime end","Every exon boundary","3 prime end"],3,"Polyadenylation follows cleavage near the 3 prime end."],["Which nucleotide residues form a typical poly(A) tail?",["Adenosine monophosphate residues","Thymidine residues","Guanosine only","Cytidine only"],0,"Poly(A) polymerase uses ATP and incorporates adenylate residues into the RNA chain."],["Which enzyme adds the poly(A) tail?",["DNA ligase","Poly(A) polymerase","Helicase","Peptidase"],1,"Poly(A) polymerase extends the cleaved RNA end."],["Is the typical nuclear mRNA poly(A) tail directly copied from a long DNA thymine tract?",["Only in plants","Yes, always","No","Only in bacteria"],2,"The tail is added enzymatically without a DNA template."],["What is a common function of the poly(A) tail?",["Destroy the nucleus","Create DNA replication forks","Join amino acids directly","Support mRNA stability and translation"],3,"Poly(A)-binding proteins support mRNA function."],["[Enrichment] Which common sequence signals cleavage and polyadenylation in many mammalian pre-mRNAs?",["AAUAAA","AUG only","UAA only","GGGCCC always"],0,"AAUAAA is a common upstream polyadenylation signal."],["Where does most nuclear pre-mRNA processing occur in eukaryotes?",["Extracellular space","Nucleus","Cell wall","Lysosome"],1,"Nuclear processing precedes export of most mature mRNAs."],["Where is mature nuclear mRNA generally exported for translation?",["Vacuole lumen","Cell wall","Cytoplasm","Extracellular matrix"],2,"Cytoplasmic ribosomes translate exported mRNA."],["Are all exons entirely protein-coding?",["Only in plants","Yes, always","Only in bacteria","No"],3,"Exons can contain untranslated regions."],["[Enrichment] What is a 5 prime UTR?",["Retained untranslated region before the coding sequence","An intron always removed","A DNA replication primer","A protein tail"],0,"The 5 prime UTR can regulate translation."],["[Enrichment] What is RNA editing?",["DNA duplication only","Alteration of RNA sequence after transcription","Protein cleavage only","Removal of all nucleotides"],1,"Editing changes selected RNA nucleotides or sequence content."],["[Enrichment] What does A-to-I RNA editing convert?",["Uracil to protein","Adenine to thymine in DNA","Adenosine to inosine","Guanine to glucose"],2,"ADAR enzymes deaminate adenosine in RNA."],["[Enrichment] What is a possible effect of a splice-site mutation?",["All proteins become identical","Guaranteed normal splicing","No RNA transcription in every case","Abnormal exon inclusion or intron retention"],3,"Altered recognition signals can disrupt splicing."],["[Enrichment] Which RNA processing event can occur in tRNA maturation?",["End trimming and base modification","Addition of a typical mRNA cap to every tRNA","Translation into protein","Replication into DNA"],0,"Pre-tRNAs undergo processing to become functional adaptors."],["Why is processing not equivalent to translation?",["Both always make DNA","Processing modifies RNA while translation makes polypeptides","Both always remove introns","Translation occurs only in the nucleus"],1,"The two processes have different substrates and products."]]);

