window.skillUpFocusedCarryingCapacityQuestions=dedicated([["Which symbol represents carrying capacity in the logistic growth equation?",["K","N","r","t"],0,"K is the sustainable population limit under the specified environmental conditions."],["Which symbol represents the current population size?",["K","N","r","t"],1,"N counts individuals, whereas K represents the environmental limit."],["Which symbol denotes the intrinsic rate of natural increase?",["N","K","r","t"],2,"The intrinsic rate r measures per capita growth without density limitation."],["For a population starting well below K with constant positive r and K, what shape does the complete logistic growth trajectory approach?",["U-shaped","J-shaped","Linear","S-shaped"],3,"Resource limitation progressively slows growth, producing a sigmoid curve."],["In the basic logistic model, what is net population growth at N = K?",["Zero","rK","K/2","2r"],0,"At N=K the factor 1−N/K equals zero."],["At what population size is total logistic growth maximal for positive constant r and K?",["K","K/2","2K","K/4"],1,"The quadratic rN(1−N/K) reaches its maximum at half K."],["For positive r, what is the sign of net growth when N exceeds K?",["Zero","Positive","Negative","Infinite"],2,"Above K the density factor is negative, so population size falls."],["What growth pattern approximates logistic growth when N is far below K?",["Instant equilibrium","Always zero","Always negative","Approximately exponential"],3,"When N/K is small the density factor approaches one."],["Which factor accounts for density limitation in the logistic equation?",["1 − N/K","N/K","K/N","1 + N/K"],0,"The factor declines from near one to zero as N approaches K."],["For N > 0, what is the per capita growth rate in the basic logistic model?",["rN","r(1 − N/K)","rK","K/N"],1,"Dividing total logistic growth by N yields the per capita rate."],["At what population size is total logistic growth maximal if K is 800?",["200","800","400","1600"],2,"Half of 800 is 400, where total growth peaks."],["Calculate 1 − N/K when N is 100 and K is 400.",["0","0.25","4","0.75"],3,"Subtract 100/400 from one to obtain 0.75."],["Calculate 1 − N/K when N is 300 and K is 600.",["0.5","2","0","1.5"],0,"Subtract 300/600 from one to obtain 0.5."],["What is net logistic growth per year when r = 0.2 per year, N = 100 and K = 200?",["20","10","40","0"],1,"Multiply 0.2 × 100 × (1−100/200) to obtain 10."],["What is net logistic growth per year when r = 0.1 per year, N = 600 and K = 300?",["30","60","−60","0"],2,"Multiply 0.1 × 600 × (1−600/300) to obtain −60."],["How may loss of a limiting resource affect carrying capacity?",["Makes K infinite","Always doubles K","Never changes K","May decrease K"],3,"Loss of resources reduces the number of individuals the habitat can support."],["How may increased availability of a limiting nutrient affect K?",["May increase K","Always reduces K","Eliminates reproduction","Makes N zero"],0,"Relieving nutrient limitation may increase sustainable population size."],["Can carrying capacity vary between seasons?",["Impossible","Possible","Only in bacteria","Only in oceans"],1,"Seasonal changes in food, water and habitat can alter K."],["Which factor becomes more restrictive as population density increases?",["Radioactive decay","Earth rotation","Competition for food","Day length alone"],2,"Competition for finite food generally intensifies with population density."],["What is meant by population overshoot?",["K equals r","N always zero","N always below K","N temporarily exceeds K"],3,"Overshoot occurs when population size temporarily exceeds sustainable capacity."],["What may happen to resources following population overshoot?",["Resource depletion","Unlimited resources","No mortality","No competition"],0,"Excess consumption can exhaust resources and increase mortality."],["Which growth model assumes unlimited resources?",["Logistic with finite K","Exponential","Density-dependent declining growth","Stable equilibrium"],1,"Exponential growth assumes no density-dependent resource constraint."],["What is per capita logistic growth when N equals K/2?",["0","rK","r/2","2r"],2,"At N=K/2 the density factor is one half."],["At a nonzero equilibrium in a closed population, how do total births and deaths compare?",["Deaths always exceed births","Both necessarily zero","Births always exceed deaths","Balance"],3,"In a closed population, equal births and deaths produce zero net growth."],["Can two species have different carrying capacities in the same habitat?",["Can differ","Always identical","Always zero","Always infinite"],0,"Different species have different resource requirements and tolerances."],["How can habitat quality influence carrying capacity?",["Never matters","Can alter K","Only changes DNA","Eliminates competition"],1,"Habitat quality affects the supply of limiting resources."],["At which population size below K is the logistic density limitation greatest?",["At N=0","Near zero","Near K","At K/1000"],2,"Near K, the density factor approaches zero and growth is strongly limited."],["Which parameters are assumed constant in the basic logistic model?",["No reproduction","Infinite K required","Zero r required","Constant r and K"],3,"The simplest logistic equation treats r and K as fixed parameters."],["What does environmental resistance encompass?",["Factors limiting growth","Unlimited food","Only mutation","Only immigration"],0,"Environmental resistance includes resource scarcity and other growth constraints."],["What does carrying capacity describe?",["Maximum individual age","Sustainable population under given conditions","Species count","Maximum birth rate"],1,"Carrying capacity is the population that can be sustained under given conditions."]]);

window.skillUpFocusedEcologicalNicheQuestions=dedicated([["[Enrichment] What does an ecological niche describe?",["Resource use, conditions and ecological role","Only location","Chromosome count","Taxonomic rank"],0,"A niche includes the conditions, resources and interactions needed for persistence."],["[Enrichment] What is the habitat of an organism?",["Entire ecological role","Physical place of residence","Genetic code","Trophic efficiency"],1,"Habitat is where an organism lives; niche describes how it lives there."],["[Enrichment] What does the fundamental niche represent?",["Only diet","Only occupied sites","Potential conditions without restrictive interactions","Only breeding season"],2,"The fundamental niche describes potential occupancy absent restrictive interactions."],["[Enrichment] What does the realized niche represent?",["Genome","Every possible condition","Entire biosphere","Conditions actually used under interactions"],3,"The realized niche reflects actual occupancy under ecological interactions."],["[Enrichment] Which interaction can restrict a species to part of its fundamental niche?",["Competition","DNA replication","Unlimited food","Identical tolerances"],0,"Competitors can exclude a species from otherwise suitable conditions."],["[Enrichment] What does niche overlap indicate?",["Identical genomes","Shared resource use","Different planets","No interactions"],1,"Overlap occurs when species share resources or environmental requirements."],["[Enrichment] How can competing species partition resources?",["Random segregation","Removal of resources","Differentiated resource use","Identical use"],2,"Partitioning reduces competition by separating resource use."],["[Enrichment] Which example illustrates temporal resource partitioning?",["Feeding in different canopy layers","Feeding on different seed sizes","Feeding in different habitats","Feeding at different times"],3,"Different feeding times reduce temporal overlap."],["[Enrichment] Which example illustrates spatial resource partitioning?",["Foraging at different canopy heights","Same branch only","Same prey simultaneously","No habitat"],0,"Different canopy heights separate foraging space."],["[Enrichment] Which example illustrates dietary resource partitioning?",["Identical diet only","Different seed sizes eaten","No food intake","Identical genes"],1,"Different seed sizes reduce dietary overlap."],["[Enrichment] What does competitive exclusion predict for complete competitors under stable limiting conditions?",["Competition always benefits both","All competitors coexist forever","Complete competitors cannot coexist indefinitely","All niches identical"],2,"Complete competitors for a limiting resource cannot persist indefinitely under stable conditions."],["[Enrichment] Who demonstrated competitive exclusion using Paramecium cultures?",["Connell","MacArthur","Hutchinson","Gause"],3,"Gause demonstrated competitive exclusion in laboratory populations."],["[Enrichment] How broad is the niche of a specialist relative to a generalist?",["Relatively narrow","Always unlimited","Absent","Every resource"],0,"Specialists use a relatively restricted range of resources."],["[Enrichment] How broad is the niche of a generalist relative to a specialist?",["Exactly one resource","Relatively broad","Absent","Zero tolerance"],1,"Generalists tolerate or exploit a broader range of conditions."],["[Enrichment] Which variable represents an abiotic niche dimension?",["Parasite species","Predator identity","Temperature","Competitor identity"],2,"Temperature is a nonliving environmental variable."],["[Enrichment] Which variable represents a biotic niche dimension?",["Light intensity","Soil pH","Temperature","Food species"],3,"Food organisms are living resources."],["[Enrichment] Can species occupy the same habitat while using different niches?",["Possible","Impossible","Only identical genomes","Only laboratory organisms"],0,"Species may coexist in the same location by using different resources."],["[Enrichment] What does niche breadth measure?",["Chromosome number","Range of resources or conditions","Body mass","Food chain length"],1,"Niche breadth measures ecological versatility across conditions and resources."],["[Enrichment] What does niche differentiation involve?",["Identical resource use","Loss of all species","Separation of resource use","DNA copying"],2,"Differentiation separates resource use and may permit coexistence."],["[Enrichment] What is ecological character displacement?",["Chromosome count only","Identical morphology everywhere","Loss of every trait","Trait divergence associated with competition"],3,"Competition can favor divergent resource-use traits in coexisting species."],["[Enrichment] Which interaction can restrict the habitats occupied by prey?",["Predation","Earth rotation","Radioactive decay","Photosynthesis alone"],0,"Predators may exclude prey from otherwise suitable habitats."],["[Enrichment] How may facilitation influence a species' actual occupancy?",["Always prevents occupancy","May expand actual occupancy","Never changes conditions","Only changes DNA"],1,"Beneficial interactions can improve stressful local conditions."],["[Enrichment] What does a multidimensional niche incorporate?",["Mass only","Latitude only","Multiple environmental axes","Population count only"],2,"A multidimensional niche combines several environmental and resource axes."],["[Enrichment] Who proposed the n-dimensional hypervolume concept of a niche?",["Mendel","Watson","Crick","Hutchinson"],3,"Hutchinson formalized the niche as an n-dimensional hypervolume."],["[Enrichment] What makes a resource limiting?",["Scarcity constrains performance","Always unlimited","Never affects growth","Always toxic"],0,"Scarcity of a limiting resource restricts growth or reproduction."],["[Enrichment] How may an invasive species affect native resource use?",["Always changes all DNA","May alter native resource use","Removes sunlight globally","Eliminates all habitats"],1,"Invasive species may compete with natives or modify ecological interactions."],["[Enrichment] Which observation supports resource partitioning among birds?",["Same chromosome count","Same feather colour","Different feeding locations","Same body mass"],2,"Different feeding locations directly indicate spatial resource partitioning."],["[Enrichment] What does a species' trophic role describe?",["Reproductive chromosome count","Chromosome length","Latitude alone","Feeding function in energy transfer"],3,"Trophic role describes how an organism obtains and transfers energy."],["[Enrichment] Can a species' niche change during its life cycle?",["May change","Always identical","Only extinct species change","Never varies"],0,"Juveniles and adults may use different habitats or foods."],["[Enrichment] How can knowledge of a species' niche support conservation?",["Guarantees survival","Identifies persistence requirements","Replaces surveys","Makes habitat irrelevant"],1,"Knowledge of niche requirements helps identify critical conservation resources."]]);

