window.skillUpFocusedEnvironmentalResistanceQuestions=dedicated([["What does environmental resistance mean in population ecology?",["Factors limiting population growth","Maximum reproductive capacity under ideal conditions","Net movement into a population","Population growth in the absence of resource limits"],0,"Resource shortages and other constraints limit realized growth."],["Which example is a biotic factor limiting population growth?",["Temperature alone","Predation","Rainfall alone","Soil pH alone"],1,"Predators are living agents affecting survival."],["Which example is an abiotic factor limiting population growth?",["Parasitism","Competition between plants","Drought","Predation"],2,"Drought is a nonliving environmental constraint."],["Which factor can become more restrictive as population density increases?",["Volcanic ash deposition","A regional frost event","A severe storm","Competition for food"],3,"Competition often intensifies as density increases."],["Which event is typically a density-independent limiting factor?",["Severe storm","Crowding competition","Density-linked disease","Territorial competition"],0,"Storm effects need not depend on population density."],["What does biotic potential describe?",["Actual growth under all constraints","Maximum reproductive capacity under ideal conditions","Carrying capacity","Death rate only"],1,"Biotic potential describes potential reproduction without limiting conditions."],["Which factor multiplies rN in the basic logistic growth equation?",["K/N","1 + N/K","1 − N/K","r alone"],2,"The density-limitation multiplier 1 − N/K decreases as N approaches K; it is not the resistance itself."],["How strong is density limitation as population size approaches carrying capacity?",["Infinite reproduction","Unlimited growth","No resource competition","Strong density limitation"],3,"Resource limitation increases as N approaches K."],["What resource assumption underlies exponential population growth?",["No resource limitation","Strong density limitation","Finite K required","No births"],0,"Exponential growth assumes constant per capita growth."],["How may food shortage affect population growth?",["Always increases reproduction","May reduce reproduction and survival","Never affects growth","Eliminates mortality"],1,"Insufficient food constrains energy available for maintenance and reproduction."],["How may high population density affect disease transmission?",["Transmission necessarily decreases","Transmission remains unchanged in every disease","Transmission may increase","Transmission necessarily reaches zero"],2,"Close contact can facilitate transmission."],["How can water scarcity affect plant growth?",["Eliminates transpiration","Always increases growth","Never affects photosynthesis","May limit growth"],3,"Water stress can reduce photosynthesis and growth."],["What happens when an essential nutrient becomes limiting?",["Scarcity constrains biomass production","All nutrients unlimited","No effect on plants","Only affects animals"],0,"Essential nutrients are required for growth."],["What is competition among members of the same species called?",["Interspecific competition","Intraspecific competition","Mutualism","Commensalism"],1,"Individuals of the same species compete for shared resources."],["What is competition between different species called?",["Intraspecific competition","Mutualism","Interspecific competition","Commensalism"],2,"Different species may compete for limiting resources."],["How may predation affect prey mortality?",["Eliminates all births","Always increases survival","Never affects abundance","Can increase mortality"],3,"Predation removes individuals from prey populations."],["How may parasites affect host fitness?",["May reduce host fitness","Always improves host fitness","Never affects reproduction","Always kills instantly"],0,"Parasites can reduce survival or reproductive output."],["How may loss of resources affect carrying capacity?",["Always increases","May decrease","Always infinite","Always unchanged"],1,"Reduced resources can support fewer individuals."],["How can population overshoot intensify environmental resistance?",["Mortality vanishes","Resources become unlimited","Resource depletion may intensify resistance","Competition stops"],2,"Excess population demand can exhaust resources."],["How is net change in a closed population calculated?",["Carrying capacity alone","Births plus deaths","Immigration alone","Births minus deaths"],3,"Without migration population change reflects births and deaths."],["In a closed population, when is net growth positive despite environmental resistance?",["Births exceed deaths","Deaths exceed births","Births equal deaths","No births"],0,"Limiting factors can reduce growth without making it negative."],["What relationship between births and deaths gives zero net growth in a closed population?",["No individual reproduces","Births equal deaths in closed population","All individuals die","Unlimited growth"],1,"Population equilibrium can coexist with ongoing reproduction."],["What factors can cause environmental resistance to vary?",["Only with chromosome count","Never","With conditions and population density","Only with species name"],2,"Limiting factors change across space and time."],["Which resource may limit growth of plants in deep shade?",["No competition","Unlimited sunlight","Unlimited nutrients","Insufficient light"],3,"Low light can constrain photosynthetic carbon gain."],["How may extreme temperatures affect survival?",["May reduce survival","Always improve survival","Never affect enzymes","Always increase reproduction"],0,"Extreme temperatures can disrupt physiological function."],["How can territoriality affect breeding opportunities?",["Always removes competition","May limit breeding opportunities","Makes habitat infinite","Eliminates density effects"],1,"Limited territories can restrict access to breeding sites."],["How can resource partitioning affect competition?",["Eliminates resources","Always increases overlap","May reduce competition","Stops reproduction"],2,"Differentiated resource use can reduce competitive pressure."],["How can the effect of environmental resistance on growth be assessed?",["Ignore mortality","Count chromosomes only","Measure leaf color only","Compare potential and realized growth"],3,"Observed growth reflects the combined effect of limiting factors."],["How can conservation address a shortage of critical resources?",["Restore critical resources","Remove all habitat","Increase pollution","Ignore ecological needs"],0,"Restoring limiting resources can improve population persistence."],["How may environmental resistance contribute to natural selection?",["Always eliminates variation","May impose differential survival","Prevents evolution","Makes all individuals identical"],1,"Environmental constraints can favor traits improving survival or reproduction."]]);

